/* ===== Parte pura: leitura da resposta e diagnóstico do erro (testável fora do navegador) ===== */
const fmt = x => (x == null || isNaN(x)) ? '' : String(+Number(x).toFixed(6)).replace('.', ',');
const same = (a, b) => Math.abs(a - b) < 1e-9 * Math.max(1, Math.abs(a), Math.abs(b));
const decs = x => { const s = String(+Number(x).toFixed(6)); const i = s.indexOf('.'); return i < 0 ? 0 : s.length - i - 1; };

function parseAns(raw) {
  let s = String(raw || '').toLowerCase().replace(/r\$|reais|real|km|metros?|kg|litros?|toneladas?|□|=/g, '').replace(/\s+/g, '');
  if (!s) return { err: 'empty' };
  if (s.indexOf(',') > -1 && s.indexOf('.') > -1) s = s.replace(/\./g, '');
  s = s.replace(',', '.');
  if (!/^-?\d+(\.\d+)?$/.test(s)) return { err: 'format' };
  return { val: parseFloat(s), txt: String(raw).trim() };
}

const PLACE = { 4: 'das dezenas de milhar', 3: 'dos milhares', 2: 'das centenas', 1: 'das dezenas', 0: 'das unidades', '-1': 'dos décimos', '-2': 'dos centésimos', '-3': 'dos milésimos', '-4': 'dos décimos de milésimo' };

function digitDiffs(c, g) {
  const dp = Math.min(6, Math.max(decs(c), decs(g)));
  const sc = Math.abs(c).toFixed(dp).split('.'), sg = Math.abs(g).toFixed(dp).split('.');
  const L = Math.max(sc[0].length, sg[0].length);
  const a = sc[0].padStart(L, '0') + (sc[1] || ''), b = sg[0].padStart(L, '0') + (sg[1] || '');
  const out = [];
  for (let i = 0; i < a.length; i++) if (a[i] !== b[i]) out.push({ exp: i < L ? L - 1 - i : -(i - L + 1), d: Math.abs(+a[i] - +b[i]) });
  return { out, sa: a, sb: b };
}

// Avalia "□ ÷ 4 + 15 = 24" com o valor g no lugar do □ -> {left, right}
function testEquation(eq, g) {
  if (!eq || eq.indexOf('=') < 0) return null;
  const parts = eq.split('=');
  const conv = t => t.replace(/□/g, '(' + g + ')').replace(/×/g, '*').replace(/÷/g, '/').replace(/−/g, '-').replace(/(\d),(\d)/g, '$1.$2');
  const l = conv(parts[0]), r = conv(parts[1]);
  if (!/^[\d.\s+\-*/()]+$/.test(l) || !/^[\d.\s+\-*/()]+$/.test(r)) return null;
  try { return { left: Function('"use strict";return (' + l + ')')(), right: Function('"use strict";return (' + r + ')')() }; } catch (e) { return null; }
}

const TAIL = {
  1: 'Confira: a vírgula está embaixo da vírgula? Você completou com zeros? Lembrou do “vai um” ou do empréstimo?',
  2: 'Confira colocando sua resposta no lugar do □: a sentença fica verdadeira?',
  3: 'Confira: contou as casas decimais de todos os fatores? Fez uma estimativa para ver se o tamanho do resultado faz sentido?',
  4: 'Confira: contou as casas e igualou (43,6 ÷ 8 vira 43,6 ÷ 8,0)? Cortou as vírgulas? Passo a passo: dividir, multiplicar, subtrair, baixar. Sobrou resto? Vírgula no quociente e zero ao lado do resto.'
};

const KIND_LABEL = {
  virgula: 'Vírgula fora do lugar', operacao: 'Operação trocada', parcial: 'Parou no meio do problema', operando: 'Respondeu com um número do enunciado',
  um_algarismo: 'Um algarismo errado', varios: 'Vários algarismos errados', parou_cedo: 'Parou a divisão cedo ou arredondou', parte_decimal: 'Erro depois da vírgula',
  parte_inteira: 'Erro na parte inteira', ordem: 'Algarismos em ordem trocada', sinal: 'Resultado negativo', perto: 'Chegou perto', longe: 'Resultado longe do esperado',
  conceito: 'Ideia da questão', escolha: 'Alternativa errada', texto: 'Resposta de texto', errado_dado: 'Repetiu o valor errado do enunciado', outro: 'Outro tipo de erro'
};
const KIND_TIP = {
  1: { virgula: 'Rever o alinhamento: vírgula embaixo de vírgula.', um_algarismo: 'Rever “vai um” e empréstimo.', parte_decimal: 'Rever como completar com zeros.' },
  2: { operacao: 'Rever a tabela de operações inversas e como traduzir o texto em conta.', parcial: 'Em problemas com dois passos, desfazer uma operação de cada vez.', virgula: 'Conferir substituindo no □.' },
  3: { virgula: 'Rever a contagem das casas decimais (soma das casas de todos os fatores) e usar estimativa.', um_algarismo: 'Rever as multiplicações parciais e os “vai um”.', varios: 'Refazer a multiplicação coluna por coluna.' },
  4: { virgula: 'Rever o método da escola: igualar as casas e cortar as vírgulas antes de dividir.', parou_cedo: 'Reforçar: se sobrou resto, coloca zero ao lado e continua.', um_algarismo: 'Rever o passo dividir, multiplicar e subtrair.' }
};

function diagnose(q, g) {
  const c = q.val, ch = q.ch, tail = TAIL[ch];
  if (g < 0) return { kind: 'sinal', msg: 'Seu resultado ficou negativo, e aqui a resposta é positiva. Veja se você não inverteu a ordem de uma subtração: o número maior vem primeiro.' };
  if (q.wrong != null && same(g, q.wrong)) return { kind: 'errado_dado', msg: 'Esse é justamente o valor errado que aparece no enunciado. Refaça a conta do zero e descubra o resultado certo.' };
  if ((q.givens || []).some(v => same(v, g))) return { kind: 'operando', msg: 'Esse número já aparece no enunciado. A resposta é o resultado de uma conta, não um dos números do problema.' };
  for (const a of (q.alts || [])) if (same(a[0], g)) {
    const trocada = a[1].indexOf('trocada') > -1;
    let m = 'Seu número parece vir de uma ' + a[1].replace(' com a ordem trocada', '') + (trocada ? ' com a ordem dos números trocada' : ' com os números do problema') + '. Releia o enunciado e pense: é essa operação que ele pede?';
    if (ch === 2) m += ' Lembre que, para descobrir o valor desconhecido, usamos a operação inversa.';
    if (trocada) m += ' Na subtração e na divisão a ordem dos números muda o resultado.';
    return { kind: 'operacao', msg: m };
  }
  if ((q.partials || []).some(v => same(v, g))) return { kind: 'parcial', msg: 'Esse número aparece no meio da conta, mas ainda não é a resposta final. Releia a pergunta do problema e veja o que falta fazer.' };
  const r = g / c;
  if (c !== 0 && g !== 0 && r > 0) {
    const k = Math.log10(r);
    if (Math.abs(k - Math.round(k)) < 1e-9 && Math.round(k) !== 0) {
      const maior = k > 0;
      const base = 'Os algarismos estão certos, mas a vírgula está no lugar errado: sua resposta está ' + (maior ? 'maior' : 'menor') + ' do que deveria. ';
      const by = { 1: 'Alinhe vírgula embaixo de vírgula e coloque a vírgula do resultado embaixo das outras.', 2: 'Os algarismos do resultado batem com a resposta correta. Falta acertar onde fica a vírgula: confira pelo valor aproximado do resultado.', 3: 'Conte as casas decimais de todos os fatores e some. Depois use uma estimativa com números redondos para saber se o resultado deve ser grande ou pequeno.', 4: 'Na divisão com vírgula, primeiro conte as casas decimais do dividendo e do divisor e IGUALE (43,6 ÷ 8 vira 43,6 ÷ 8,0). Depois corte as vírgulas (436 ÷ 80) e divida. Use a tira-prova (quociente × divisor).' };
      return { kind: 'virgula', msg: base + by[ch] };
    }
  }
  const dg = decs(g), dc = decs(c);
  if (dg < dc) {
    const f = Math.pow(10, dg);
    if (same(Math.trunc(c * f) / f, g)) return { kind: 'parou_cedo', msg: ch === 4 ? 'Você acertou até onde chegou, mas a divisão ainda não terminou: o resto não deu zero. Coloque um zero ao lado do resto e continue dividindo.' : 'O começo está certo, mas faltaram casas decimais no final. Confira a conta até o último algarismo.' };
    if (same(Math.round(c * f) / f, g)) return { kind: 'parou_cedo', msg: 'Parece que você arredondou. Aqui o resultado tem mais casas decimais: continue a conta até o resto ser zero, sem arredondar.' };
  }
  const D = digitDiffs(c, g);
  const sa = D.sa.split('').sort().join(''), sb = D.sb.split('').sort().join('');
  if (D.out.length >= 2 && sa === sb) return { kind: 'ordem', msg: 'Você usou os algarismos certos, mas em ordem diferente. Veja de novo a ordem em que escreveu o resultado.' };
  if (D.out.length === 1) {
    const o = D.out[0], p = PLACE[o.exp] || 'de uma das casas';
    const by = { 1: 'Refaça só essa coluna.', 2: 'Substitua sua resposta no □ para ver o que não fecha.', 3: 'Refaça a multiplicação dessa coluna.', 4: 'Refaça só esse passo da divisão: dividir, multiplicar e subtrair.' };
    return { kind: 'um_algarismo', msg: 'Está bem perto! Só o algarismo ' + p + ' está diferente. ' + (o.d === 1 ? 'Ele errou por 1 a mais ou a menos, o que costuma ser um “vai um” ou um empréstimo. ' : 'Ele errou por mais de 1, então confira a tabuada daquela casa. ') + by[ch] };
  }
  if (D.out.length === 2) {
    const ps = D.out.map(o => PLACE[o.exp] || 'de uma casa');
    return { kind: 'varios', msg: 'Você acertou a maior parte, mas 2 algarismos estão diferentes: os algarismos ' + ps[0] + ' e ' + ps[1] + '. Refaça a conta com calma, uma coluna de cada vez.' };
  }
  if (Math.trunc(Math.abs(c)) === Math.trunc(Math.abs(g))) return { kind: 'parte_decimal', msg: 'A parte inteira está certa. O erro está depois da vírgula. ' + tail };
  const fc = (Math.abs(c).toFixed(6).split('.')[1] || ''), fg = (Math.abs(g).toFixed(6).split('.')[1] || '');
  if (fc === fg) return { kind: 'parte_inteira', msg: 'A parte depois da vírgula está certa. O erro está na parte inteira do resultado.' };
  if (Math.abs(g - c) / Math.max(Math.abs(c), 1) < 0.05) return { kind: 'perto', msg: 'Você chegou perto, mas ainda não é. Refaça a conta conferindo cada passo. ' + tail };
  const rel = g > c ? 'maior' : 'menor';
  return { kind: 'longe', msg: 'Seu resultado ficou bem ' + rel + ' do que deveria. Faça uma estimativa com números redondos e compare com a sua resposta. ' + tail };
}

// Mensagem de conferência, sem entregar a resposta
function proofText(q, g) {
  const t = testEquation(q.eq, g);
  if (t && !same(t.left, t.right)) return 'Teste: colocando ' + fmt(g) + ' no lugar do □, a conta dá ' + fmt(t.left) + '. Mas deveria dar ' + fmt(t.right) + ' (' + (t.left > t.right ? 'passou' : 'ficou abaixo') + ').';
  const p = q.proof;
  if (!p) return '';
  if (p.op === '/') return 'Tira-prova: ' + fmt(g) + ' × ' + fmt(p.b) + ' dá ' + fmt(g * p.b) + ', mas o dividendo é ' + fmt(p.a) + '. Os dois deveriam ser iguais.';
  if (p.op === '+') return 'Tira-prova: ' + fmt(g) + ' − ' + fmt(p.b) + ' dá ' + fmt(g - p.b) + ', e deveria dar ' + fmt(p.a) + '.';
  if (p.op === '-') return 'Tira-prova: ' + fmt(g) + ' + ' + fmt(p.b) + ' dá ' + fmt(g + p.b) + ', e deveria dar ' + fmt(p.a) + '.';
  if (p.op === '*') { const x = g / p.b; return 'Tira-prova: ' + fmt(g) + ' ÷ ' + fmt(p.b) + ' ' + (same(x * p.b, g) && decs(x) <= 4 ? 'dá ' + fmt(x) : 'não dá um número certinho') + ', e deveria dar ' + fmt(p.a) + '.'; }
  return '';
}

if (typeof module !== 'undefined') module.exports = { fmt, same, parseAns, diagnose, proofText, digitDiffs, testEquation };


/* ===== Núcleo compartilhado (app do aluno e painel do responsável) ===== */
const LV = { 1: 'Fácil', 2: 'Médio', 3: 'Difícil' };
const BLK = { a: { n: 'Aquecimento', c: 1 }, t: { n: 'Treino', c: 2 }, p: { n: 'Problemas', c: 3 }, c: { n: 'Contas', c: 2 } };
const BASE_XP = { 1: 10, 2: 20, 3: 30 };
const PHOTO_XP = 5;
const RANKS = [[0, 'Aprendiz'], [200, 'Explorador'], [600, 'Calculista'], [1200, 'Estrategista'], [2000, 'Mestre do Treino']];
const DEFAULT_CFG = { confReq: true, photoReq: true, minMin: 12, freeDay: 0 };
const MAXMS = 180000;

const esc = s => String(s == null ? '' : s).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const rankOf = xp => { let r = 0; RANKS.forEach((x, i) => { if (xp >= x[0]) r = i; }); return r; };
const pct = (a, b) => b ? Math.round(a / b * 100) : 0;
const ymd = ts => { const d = new Date(ts); return d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0') + '-' + String(d.getDate()).padStart(2, '0'); };
const newCid = () => (self.crypto && crypto.randomUUID) ? crypto.randomUUID() : 'c' + Date.now().toString(36) + Math.random().toString(36).slice(2, 10);

/* Junta os pacotes de matérias numa lista de questões */
function buildIndex(PACKS) {
  const QUESTIONS = [], byId = {}, byDay = {}, plans = {};
  PACKS.forEach(pk => {
    (pk.questions || []).forEach(q => { q.subject = q.subject || pk.id; QUESTIONS.push(q); byId[q.id] = q; if (q.day) { const k = pk.id + ':' + q.day; (byDay[k] = byDay[k] || []).push(q); } });
    if (pk.plan) plans[pk.id] = pk.plan;
  });
  return { QUESTIONS, byId, byDay, plans };
}

/* Progresso por questão, XP, estrelas e sequência, a partir dos eventos */
function computeProg(QUESTIONS, byId, attempts) {
  const P = {};
  QUESTIONS.forEach(q => P[q.id] = { tries: 0, solved: false, helped: false, skipped: false, firstOk: false, wrongSure: 0, luckOk: false, kinds: [], answers: [], ms: 0, ms1: null, hints: 0,
    stars: 0, xp: 0, photo: 0, photoSkip: false, photoPending: false, lastTs: 0 });
  let streak = 0;
  attempts.slice().sort((a, b) => a.ts - b.ts).forEach(a => {
    const p = P[a.qid], q = byId[a.qid]; if (!p) return;
    p.lastTs = Math.max(p.lastTs, a.ts);
    if (a.type === 'try') {
      p.ms += Math.min(a.ms || 0, MAXMS);
      if (a.rev) return;
      p.tries++; if (p.tries === 1 && a.ok) p.firstOk = true; if (p.ms1 == null) p.ms1 = a.ms;
      if (a.ok) {
        if (!p.solved) { p.stars = p.tries === 1 ? 3 : p.tries === 2 ? 2 : 1; p.xp = Math.round(BASE_XP[q.lv] * (p.tries === 1 ? 1.5 : p.tries === 2 ? 1 : 0.5)); }
        p.solved = true; if (a.conf === 'chutei') p.luckOk = true; streak++;
      } else { p.answers.push(a.ans); if (a.kind) p.kinds.push(a.kind); if (a.conf === 'certeza') p.wrongSure++; streak = 0; }
    } else if (a.type === 'skip') p.skipped = true;
    else if (a.type === 'hint') p.hints++;
    else if (a.type === 'help') p.helped = true;
    else if (a.type === 'foto') { p.photo++; if (!a.path) p.photoPending = true; }
    else if (a.type === 'foto_skip') p.photoSkip = true;
  });
  let xp = 0, stars = 0;
  QUESTIONS.forEach(q => { const p = P[q.id]; xp += p.xp + (p.photo ? PHOTO_XP : 0); stars += p.stars; });
  return { P, xp, stars, streak };
}

/* Uma questão está "fechada" quando foi resolvida (e a foto pedida foi enviada ou dispensada) ou quando ele pediu ajuda */
function isClosed(q, p, cfg) {
  if (p.helped) return true;
  if (!p.solved) return false;
  if (q.photo && cfg.photoReq && !p.photo && !p.photoSkip) return false;
  return true;
}

function dayInfo(byDay, subject, day, P, cfg) {
  const qs = byDay[subject + ':' + day] || [];
  let closed = 0, ms = 0, solved = 0, first = 0, last = 0, photoMiss = 0, helped = 0;
  qs.forEach(q => { const p = P[q.id]; if (isClosed(q, p, cfg)) closed++; if (p.solved) solved++; if (p.firstOk) first++; if (p.helped) helped++; ms += p.ms; last = Math.max(last, p.lastTs);
    if (q.photo && cfg.photoReq && p.solved && !p.photo && !p.photoSkip) photoMiss++; });
  const allClosed = qs.length > 0 && closed === qs.length;
  const needMs = (cfg.minMin || 0) * 60000;
  const timeOk = ms >= needMs;
  return { qs, total: qs.length, closed, solved, first, helped, ms, last, photoMiss, allClosed, timeOk, done: allClosed && timeOk, needMs };
}

/* Situação do plano: dia atual e se hoje já foi feito */
function planState(byDay, subject, plan, P, cfg, now) {
  const days = plan.map(d => dayInfo(byDay, subject, d.day, P, cfg));
  let cur = plan.findIndex((d, i) => !days[i].done);
  if (cur < 0) return { days, cur: -1, status: 'fim' };
  const today = ymd(now || Date.now());
  const prev = cur > 0 ? days[cur - 1] : null;
  const rest = prev && prev.last && ymd(prev.last) === today && (cfg.freeDay || 0) < plan[cur].day;
  return { days, cur, status: rest ? 'descanso' : 'aberto' };
}

if (typeof module !== 'undefined') module.exports = { LV, BLK, BASE_XP, RANKS, DEFAULT_CFG, rankOf, pct, ymd, buildIndex, computeProg, isClosed, dayInfo, planState };

/* ===== Camada de nuvem (Supabase). Se não houver configuração, o app funciona só neste aparelho. ===== */
const Cloud = (function () {
  const C = window.APP_CFG || {};
  let sb = null, user = null;
  const enabled = !!(C.url && C.key && window.supabase);
  const COLS = ['cid', 'ts', 'type', 'qid', 'ch', 'lv', 'day', 'ans', 'val', 'ok', 'kind', 'conf', 'ms', 'rev', 'path', 'note'];
  const clean = e => { const o = {}; COLS.forEach(k => { if (e[k] !== undefined) o[k] = e[k]; }); return o; };

  async function init() {
    if (!enabled) return null;
    sb = window.supabase.createClient(C.url, C.key, { auth: { persistSession: true, autoRefreshToken: true, storageKey: 'decimais-auth' } });
    const { data } = await sb.auth.getSession();
    user = data && data.session ? data.session.user : null;
    sb.auth.onAuthStateChange((_ev, s) => { user = s ? s.user : null; });
    return user;
  }
  async function login(email, pw) {
    const { data, error } = await sb.auth.signInWithPassword({ email: String(email).trim(), password: pw });
    if (error) return { error: error.message || 'erro' };
    user = data.user; return { user };
  }
  async function logout() { if (sb) await sb.auth.signOut(); user = null; }
  const role = () => (user && user.app_metadata && user.app_metadata.role) || '';

  async function pushEvents(list) {
    if (!sb || !user || !list.length) return { ok: true };
    const rows = list.map(clean);
    const { error } = await sb.from('events').upsert(rows, { onConflict: 'cid', ignoreDuplicates: true });
    return error ? { error: error.message } : { ok: true };
  }
  async function fetchEvents() {
    if (!sb || !user) return null;
    let out = [], from = 0; const step = 1000;
    for (;;) {
      const { data, error } = await sb.from('events').select('*').order('ts', { ascending: true }).range(from, from + step - 1);
      if (error) return null;
      out = out.concat(data); if (data.length < step) break; from += step; if (from > 50000) break;
    }
    return out;
  }
  async function pushFlag(f) {
    if (!sb || !user) return { ok: true };
    const row = { user_id: user.id, qid: f.qid, doubt: !!f.doubt, help: !!f.help, note: f.note || '', ts: f.ts || Date.now() };
    const { error } = await sb.from('flags').upsert(row, { onConflict: 'user_id,qid' });
    return error ? { error: error.message } : { ok: true };
  }
  async function fetchFlags() {
    if (!sb || !user) return null;
    const { data, error } = await sb.from('flags').select('*');
    return error ? null : data;
  }
  async function fetchConfig() {
    if (!sb || !user) return null;
    const { data, error } = await sb.from('config').select('key,value');
    if (error) return null;
    const o = {}; data.forEach(r => o[r.key] = r.value); return o;
  }
  async function saveConfig(key, value) {
    const { error } = await sb.from('config').upsert({ key, value }, { onConflict: 'key' });
    return error ? { error: error.message } : { ok: true };
  }
  async function upload(path, blob) {
    if (!sb || !user) return { error: 'offline' };
    const { error } = await sb.storage.from('cadernos').upload(path, blob, { contentType: 'image/jpeg', upsert: true });
    return error ? { error: error.message } : { ok: true };
  }
  async function signedUrls(paths) {
    if (!sb || !user || !paths.length) return {};
    const { data, error } = await sb.storage.from('cadernos').createSignedUrls(paths, 3600);
    if (error || !data) return {};
    const o = {}; data.forEach(r => { if (r.signedUrl) o[r.path] = r.signedUrl; }); return o;
  }
  async function deleteQuestion(qid) {
    const a = await sb.from('events').delete().eq('qid', qid);
    const b = await sb.from('flags').delete().eq('qid', qid);
    return (a.error || b.error) ? { error: (a.error || b.error).message } : { ok: true };
  }
  async function deleteAll() {
    const a = await sb.from('events').delete().neq('cid', '');
    const b = await sb.from('flags').delete().neq('qid', '');
    return (a.error || b.error) ? { error: (a.error || b.error).message } : { ok: true };
  }
  return { enabled, init, login, logout, role, pushEvents, fetchEvents, pushFlag, fetchFlags, fetchConfig, saveConfig, upload, signedUrls, deleteQuestion, deleteAll, user: () => user };
})();

const CHAPS=[{"num": 1, "title": "Adição e subtração com números decimais", "short": "Somar e subtrair", "book": "Livro: páginas 13 a 18", "steps": ["Escreva os números <b>um embaixo do outro</b>, com <b>vírgula embaixo de vírgula</b>.", "<b>Complete com zeros</b> à direita, até todos os números terem a mesma quantidade de casas depois da vírgula. (Número inteiro tem vírgula escondida no final: 148 = 148,00.)", "Some ou subtraia como nos números naturais, da <b>direita para a esquerda</b>. Na soma use o “vai um”; na subtração, o empréstimo.", "Coloque a vírgula no resultado, <b>bem embaixo das outras vírgulas</b>.", "Confira: faça uma estimativa (12,45 + 3,6 está perto de 12 + 4 = 16) e, na subtração, some o resultado com o número que foi tirado."], "why": "Só podemos juntar “coisas do mesmo tamanho”: décimos com décimos, centésimos com centésimos. Por isso a vírgula é a linha-guia da conta.", "examples": [{"t": "Exemplo 1 · soma: 12,45 + 3,6", "lines": ["   1 2 , 4 5", " +   3 , 6 0     <- completei com um zero", " -------------", "   1 6 , 0 5"], "note": "5 + 0 = 5; 4 + 6 = 10 (escreve 0, vai 1); 2 + 3 + 1 = 6; 1 desce. Resultado: 16,05."}, {"t": "Exemplo 2 · subtração: 90 − 12,48", "lines": ["   9 0 , 0 0     <- 90 = 90,00", " - 1 2 , 4 8", " -------------", "   7 7 , 5 2"], "note": "Quando faltar, peça emprestado ao vizinho da esquerda, como na conta de números naturais. Resultado: 77,52."}], "errors": ["Alinhar os números pela <b>direita</b> em vez de alinhar pela <b>vírgula</b> (12,25 + 3,4 não é 12,59!).", "Esquecer de completar com zeros antes de subtrair (0,75 − 0,5 vira 0,75 − 0,50).", "Esquecer a vírgula no resultado."]}, {"num": 2, "title": "Encontrando um valor desconhecido", "short": "Valor desconhecido", "book": "Livro: páginas 30 a 34", "steps": ["<b>Leia</b> e descubra o que ainda não se sabe. Esse é o valor desconhecido: represente por <b>□</b> (ou por uma letra, como x).", "<b>Escreva a sentença</b> com o □ no lugar certo.", "Troque pela <b>operação inversa</b> (tabela abaixo) e calcule.", "<b>Confira</b>: coloque a resposta no lugar do □ e veja se a sentença original fica verdadeira."], "why": "Uma operação “desfaz” a outra: se você somou 8, para voltar ao início é só tirar 8. Se multiplicou por 6, divida por 6.", "examples": [{"t": "Exemplo 1 · O triplo de um número é 123. Que número é esse?", "lines": ["3 × □ = 123", "□ = 123 ÷ 3", "□ = 41", "Conferindo: 3 × 41 = 123  ✓"], "note": "“Triplo” é × 3. Para achar o □, usamos a inversa da multiplicação: a divisão."}, {"t": "Exemplo 2 · Elisa gastou R$ 132,58 no total. O lápis custou R$ 56,30. Quanto custaram as canetinhas?", "lines": ["R$ 56,30 + □ = R$ 132,58", "□ = R$ 132,58 − R$ 56,30", "□ = R$ 76,28", "Conferindo: 56,30 + 76,28 = 132,58  ✓"], "note": "Parte + parte = total. Para achar a parte que falta: total − parte conhecida."}], "errors": ["Usar a mesma operação da sentença (somar de novo em vez de tirar).", "Inverter errado quando o □ é o que se tira (31 − □ = 15) ou o divisor (42 ÷ □ = 7).", "Não conferir a resposta no final."]}, {"num": 3, "title": "Multiplicação com números decimais", "short": "Multiplicar", "book": "Livro: páginas 65 a 70", "steps": ["Arme a conta alinhando os números pela <b>direita</b>, como se fossem naturais. <b>Aqui não alinhamos a vírgula</b> (diferente da soma!).", "<b>Ignore as vírgulas</b> e multiplique normalmente, da direita para a esquerda.", "<b>Conte as casas decimais</b> de <b>todos</b> os fatores e some. Exemplo: 0,25 tem 2 casas e 9 tem 0, então o resultado tem 2 casas.", "No resultado, conte essa quantidade de casas <b>da direita para a esquerda</b> e coloque a vírgula.", "Confira com uma <b>estimativa</b>: 12,5 × 6 é perto de 12 × 6 = 72, então o resultado é perto de 72 (75, e não 7,5 nem 750)."], "why": "0,25 são 25 centésimos. 25 centésimos × 9 = 225 centésimos, ou seja, 2,25. Contar as casas decimais é só uma forma rápida de transformar os “centésimos” de volta em número com vírgula.", "examples": [{"t": "Exemplo 1 · 0,25 × 9  (parecido com o do livro)", "lines": ["    2   4      <- “vai”", "    0 , 2 5    (2 casas)", "  ×       9    (0 casas)", "  -----------", "    2 , 2 5    (2 + 0 = 2 casas)"], "note": "Sem vírgula: 25 × 9 = 225. Dois fatores com 2 casas no total, então 2,25."}, {"t": "Exemplo 2 · 12,5 × 6", "lines": ["   1 3          <- “vai”", "   1 2 , 5      (1 casa)", " ×       6      (0 casas)", " ------------", "   7 5 , 0      (1 casa)  =  75"], "note": "125 × 6 = 750. Uma casa decimal: 75,0, que é igual a 75."}, {"t": "Exemplo 3 · 3,4 × 2,5  (dois fatores com vírgula)", "lines": ["      3 4        (1 casa)", "  ×   2 5        (1 casa)", "  ---------", "    1 7 0        <- 34 × 5", "  + 6 8 0        <- 34 × 2, deslocado uma casa", "  ---------", "    8 5 0   ->  8,50   (1 + 1 = 2 casas)"], "note": "Não esqueça: ao multiplicar pelo algarismo das dezenas, a linha começa um lugar para a esquerda (ou coloque um zero no fim). Resultado: 8,5."}], "errors": ["Alinhar as vírgulas como na soma. Na multiplicação, alinha-se pela direita.", "Contar as casas decimais de só <b>um</b> dos fatores. É a <b>soma</b> das casas de todos.", "Esquecer de deslocar a segunda linha (ou o zero) ao multiplicar pelo algarismo das dezenas.", "Não estimar: se 12,5 × 6 deu 7,5, a estimativa (perto de 72) mostra na hora que a vírgula está errada."]}, {"num": 4, "title": "Divisão com números decimais (método da escola)", "short": "Dividir", "book": "Livro: páginas 74 a 83", "steps": ["<b>Conte as casas decimais</b> do dividendo e do divisor. Exemplo: 43,6 ÷ 8 → 43,6 tem 1 casa e 8 tem 0.", "<b>Iguale as casas</b>: complete com zeros para os dois terem o mesmo número de casas. 43,6 ÷ 8 vira 43,6 ÷ <b>8,0</b>.", "<b>Corte as vírgulas</b> dos dois. 43,6 ÷ 8,0 vira 436 ÷ 80.", "Divida como número natural: <b>dividir → multiplicar → subtrair → baixar</b>.", "Se sobrar resto e a conta não acabou: coloque <b>vírgula no quociente</b> e um <b>zero ao lado do resto</b>. Continue até o resto dar 0.", "<b>Tira-prova</b>: quociente × divisor tem que dar o dividendo."], "why": "Igualar as casas e cortar as vírgulas é o mesmo que multiplicar os dois números pela mesma potência de 10: o resultado da divisão não muda, mas a conta fica só com números inteiros. Foi esse passo (igualar) que a professora cobrou na prova.", "examples": [{"t": "Exemplo 1 · 43,6 ÷ 8  (a conta da prova)", "lines": ["43,6 ÷ 8      1 casa e 0 casa", "43,6 ÷ 8,0     igualei as casas", "436 ÷ 80       cortei as vírgulas", "436 ÷ 80 = 5, resto 36", "360 ÷ 80 = 4, resto 40", "400 ÷ 80 = 5, resto 0", "Resultado: 5,45"], "note": "Tira-prova: 5,45 × 8 = 43,6. ✓"}, {"t": "Exemplo 2 · 382 ÷ 5  (inteiros, sobra resto)", "lines": ["38 ÷ 5 = 7, resto 3", "32 ÷ 5 = 6, resto 2", "vírgula no quociente: 20 ÷ 5 = 4", "Resultado: 76,4"], "note": "Tira-prova: 76,4 × 5 = 382. ✓"}, {"t": "Exemplo 3 · 7,5 ÷ 2,5  (os dois têm vírgula)", "lines": ["1 casa e 1 casa: já estão iguais", "corta as vírgulas: 75 ÷ 25", "75 ÷ 25 = 3", "Resultado: 3"], "note": "Tira-prova: 3 × 2,5 = 7,5. ✓"}], "errors": ["Dividir 436 ÷ 8 sem igualar: o 8 precisa virar 8,0 antes de cortar as vírgulas.", "Cortar a vírgula de um número só.", "Esquecer a vírgula no quociente quando passa a dividir décimos.", "Esquecer o zero ao lado do resto.", "Parar quando sobra resto, sem perceber que dá para continuar."]}, {"num": 5, "title": "Roteiro para resolver problemas", "short": "Problemas", "book": "Vale para qualquer problema", "steps": ["<b>Leia duas vezes</b> e sublinhe a pergunta.", "<b>Marque os dados</b> (os números e o que cada um significa).", "<b>Escreva os passos</b> antes de calcular. Pergunte-se: gastou? sobrou? juntou? repartiu?", "<b>Calcule um passo de cada vez</b>, no caderno, com a conta armada.", "<b>Estime ou confira</b>: o resultado faz sentido? Faça a tira-prova.", "<b>Responda a pergunta</b> com uma frase, usando o último resultado."], "why": "Muitos erros não estão na conta, e sim em parar no meio ou responder outra coisa. Sublinhar a pergunta e escrever os passos evita isso.", "examples": [{"t": "Exemplo · Ana tinha R$ 50,00, gastou R$ 12,50 e depois R$ 8,30. Quanto sobrou?", "lines": ["Pergunta: quanto sobrou?", "Gastou: 12,50 + 8,30 = 20,80", "Sobrou: 50,00 − 20,80 = 29,20", "Resposta: sobraram R$ 29,20."], "note": "Dois passos. Se parasse em 20,80 estaria respondendo quanto gastou, não quanto sobrou."}], "errors": ["Parar no meio (responder o resultado do primeiro passo).", "Usar a operação do primeiro verbo que aparece.", "Não responder à pergunta feita."]}];
